void BLACKicon(unsigned int x,unsigned int y )
{
    int  i;
    int  j;

    for(i=0;i<30;i++)
    {
        for(j=0;j<30;j++)
        {
            Pixel(x+j, i+y, 0x0000);
        }
    }
}


void Foldericon(unsigned int x,unsigned int y )
{
    int  i;
    int  j;
    unsigned int COLOR;
    unsigned int counter=70;
    unsigned int LOWBYTE;
    unsigned int HIGHBYTE;

    for(i=0;i<30;i++)
    {
        for(j=0;j<30;j++)
        {
            LOWBYTE=folder1[counter];counter++;
            HIGHBYTE=folder1[counter];counter++;
            COLOR=((HIGHBYTE<<8)|LOWBYTE);
            Pixel(x+j, i+y, COLOR);
        }
    }
}





void AVIicon(unsigned int x,unsigned int y )
{
    unsigned int row;
    unsigned int col;
    unsigned int off;
    unsigned int stride;
    unsigned int p;
    unsigned int bmp_row;
    unsigned char b;
    unsigned char g;
    unsigned char r;
    unsigned int color;

    off = (unsigned int)avi_icon_bmp[10] | ((unsigned int)avi_icon_bmp[11] << 8);
    stride = (unsigned int)((30u*3u + 3u) & (~3u));

    for(row=0; row<30u; row++)
    {
        bmp_row = 29u - row;
        p = off + (unsigned int)(bmp_row * stride);

        for(col=0; col<30u; col++)
        {
            b = avi_icon_bmp[p + (unsigned int)(col*3u) + 0u];
            g = avi_icon_bmp[p + (unsigned int)(col*3u) + 1u];
            r = avi_icon_bmp[p + (unsigned int)(col*3u) + 2u];

            color = ((unsigned int)(r & 0xF8u) << 8) | ((unsigned int)(g & 0xFCu) << 3) | ((unsigned int)(b) >> 3);

            Pixel(x+col, row+y, color);
        }
    }
}



